def transform(grid):
    G=np.array(grid); H,W=G.shape
    pts=[(r,c,int(G[r,c])) for r in range(H) for c in range(W) if G[r,c] not in (0,8)]
    rmin=min(p[0] for p in pts); rmax=max(p[0] for p in pts)
    cmin=min(p[1] for p in pts); cmax=max(p[1] for p in pts)
    M=np.zeros((rmax-rmin+1,cmax-cmin+1),int)
    for r,c,val in pts: M[r-rmin,c-cmin]=val
    mp=np.rot90(M,3)
    occ=G==8
    seen=np.zeros_like(occ); comps=[]
    for r in range(H):
        for c in range(W):
            if occ[r,c] and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            xx,yy=a+dr,b+dc
                            if 0<=xx<H and 0<=yy<W and occ[xx,yy] and not seen[xx,yy]:
                                seen[xx,yy]=True; stack.append((xx,yy))
                comps.append(cells)
    out=G.copy()
    if not comps: return [list(map(int,row)) for row in out]
    rminb=min(min(cc[0] for cc in comp) for comp in comps)
    rmaxb=max(max(cc[0] for cc in comp) for comp in comps)+1
    cminb=min(min(cc[1] for cc in comp) for comp in comps)
    cmaxb=max(max(cc[1] for cc in comp) for comp in comps)+1
    hh,ww=rmaxb-rminb,cmaxb-cminb
    nz=int((mp!=0).sum())
    scale=max([u for u in range(gcd(hh,ww),0,-1) if hh%u==0 and ww%u==0 and (hh//u)*(ww//u)==nz] or [1])
    nr,nc=hh//scale,ww//scale
    U=np.zeros((nr,nc),int)
    for r in range(nr):
        for c in range(nc):
            if (G[rminb+r*scale:rminb+(r+1)*scale, cminb+c*scale:cminb+(c+1)*scale]==8).any(): U[r,c]=1
    seq=[int(val) for row in mp for val in row if val]
    comps.sort(key=lambda comp:(min(cc[0] for cc in comp), min(cc[1] for cc in comp)))
    unit_owner={}
    for r in range(nr):
        for c in range(nc):
            if U[r,c]:
                cellset=set()
                for a in range(scale):
                    for b in range(scale):
                        cellset.add((rminb+r*scale+a, cminb+c*scale+b))
                for ci,comp in enumerate(comps):
                    if cellset & set(comp):
                        unit_owner[(r,c)]=ci; break
    ci_colors={}
    for idx,(rc,ci) in enumerate(sorted(unit_owner.items())):
        ci_colors.setdefault(ci, seq[idx] if idx<len(seq) else 1)
    for ci,colv in ci_colors.items():
        for (a,b) in comps[ci]: out[a,b]=colv
    return [list(map(int,row)) for row in out]

